def rule_page12_common_stock_spans_near_section12b(doc: dict) -> list[dict]:
    """Match common-stock title spans that sit inside the page-1/2 Section 12(b) listing block."""
    try:
        import re

        texts = doc.get("texts", [])
        results = []

        for i, span in enumerate(texts):
            if span.get("page_no", 999) > 2:
                continue

            lowered = span.get("text", "").lower()
            if (
                "aggregate market value" in lowered
                or "shares outstanding" in lowered
                or "number of shares outstanding" in lowered
            ):
                continue

            if not (
                "common stock" in lowered
                or "ordinary shares" in lowered
                or re.search(r"class\s+[a-z]\s+common stock", lowered)
            ):
                continue

            start = max(0, i - 8)
            end = min(len(texts), i + 8)
            window = " ".join(
                texts[j].get("text", "").lower()
                for j in range(start, end)
            )
            if any(
                marker in window
                for marker in (
                    "section 12(b)",
                    "trading symbol",
                    "exchange on which registered",
                )
            ):
                results.append(span)

        return results
    except Exception:
        return []

def rule_page12_section12b_common_stock_tables(doc: dict) -> list[dict]:
    """Match page-1/2 Section 12(b) tables that include the common-stock listing row."""
    try:
        return [
            s
            for s in doc.get("texts", [])
            if s.get("page_no", 999) <= 2
            and s.get("label") == "table"
            and "exchange on which registered" in s.get("text", "").lower()
            and (
                "common stock" in s.get("text", "").lower()
                or "ordinary shares" in s.get("text", "").lower()
            )
        ]
    except Exception:
        return []

def rule_apple_page1_first_exchange_after_section12b(doc: dict) -> list[dict]:
    """Match Apple cover-page Section 12(b) spans plus the first exchange mention after that anchor."""
    try:
        doc_name = (
            doc.get("doc_name")
            or doc.get("origin", {}).get("filename")
            or ""
        ).lower()
        if "apple" not in doc_name:
            return []

        texts = doc.get("texts", [])
        anchor = None
        for i, span in enumerate(texts):
            if span.get("page_no") == 1 and "section 12(b)" in span.get("text", "").lower():
                anchor = i
                break

        if anchor is None:
            return []

        results = []
        seen = set()
        found_exchange = False

        for i in range(anchor, min(len(texts), anchor + 55)):
            span = texts[i]
            if span.get("page_no") != 1:
                continue

            lowered = span.get("text", "").lower()
            if "indicate by check mark" in lowered or "section 12(g)" in lowered:
                break

            keep = (
                "aapl" in lowered
                or "common stock" in lowered
                or "name of each exchange on which registered" in lowered
                or "trading symbol" in lowered
            )
            if not found_exchange and (
                "nasdaq" in lowered or "new york stock exchange" in lowered
            ):
                keep = True
                found_exchange = True

            if keep:
                idx = id(span)
                if idx not in seen:
                    seen.add(idx)
                    results.append(span)

        return results
    except Exception:
        return []

